\item OpenAI, \emph{Primitive roots for every admissible integer base}, 2026-10-04; citation key \texttt{OAI:Primitive-roots-for-every-admissible-integer-base-October-4-2026}. \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/primitive-roots-all-integer-bases.pdf}{PDF (GitHub)}; \href{https://github.com/openai/math/raw/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/primitive-roots-all-integer-bases.pdf}{PDF (direct)}; \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/README.md}{Manuscript page and citation}; \href{https://github.com/openai/math/blob/main/preprints/Primitive-roots-for-every-admissible-integer-base-October-4-2026/primitive-roots-all-integer-bases.pdf}{Latest version}.
\item OpenAI, \emph{Simultaneous primitive roots: a conditional lower bound for prime bases}, 2026-10-04; citation key \texttt{OAI:Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026}. \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf}{PDF (GitHub)}; \href{https://github.com/openai/math/raw/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf}{PDF (direct)}; \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/README.md}{Manuscript page and citation}; \href{https://github.com/openai/math/blob/main/preprints/Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026/simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf}{Latest version}.
\item \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/CONTENTS.md}{OpenAI catalogue entry}.
